        <div key={i} style={{
          position: 'absolute',
          left: b.cx, top: b.cy,
          width: b.size, height: b.size,
          transform: 'translate(-50%, -50%)',
          background: `radial-gradient(circle, ${b.color} 0%, transparent 70%)`,
          opacity: b.opacity,
          filter: 'blur(40px)',
          borderRadius: '50%',
